package com.worklink.controller;import com.worklink.dto.matching.MatchResult;import com.worklink.service.MatchingService;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController public class MatchingController {final MatchingService s;public MatchingController(MatchingService x){s=x;}@GetMapping("/api/client/projects/{id}/matches")@PreAuthorize("hasRole('CLIENT')")List<MatchResult> matches(@PathVariable Long id,@RequestParam(defaultValue="10") int limit){return s.matches(id,limit);}@GetMapping("/api/freelancer/projects/{id}/match")@PreAuthorize("hasRole('FREELANCER')")MatchResult mine(@PathVariable Long id){return s.mine(id);}}
